try {
  const parsed = JSON.parse($json.stdout);
  return { ...parsed, projectName, notifyEmail };
} catch (e) {
  return {
    projectName,
    notifyEmail,
    parseError: e.message,
    rawStdout: ($json.stdout || '').slice(0, 500),
    exitCode: $json.exitCode,
  };
}

